#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

using ll = long long;
const ll INF = 4e18; 
int N;
ll K;
// 定义矩阵结构
using Mat = vector<vector<ll>>;

// 广义矩阵乘法 (Min-Plus Matrix Multiplication)
// C[i][j] = min(A[i][k] + B[k][j])
Mat mul(const Mat &A, const Mat &B) {
    Mat C(N, vector<ll>(N, INF));
    // i-k-j 循环顺序，利于缓存和剪枝
    for (int i = 0; i < N; i++) {
        for (int k = 0; k < N; k++) {
            // 剪枝：如果前半段不可达，则无需计算后半段
            if (A[i][k] == INF) continue;
            for (int j = 0; j < N; j++) {
                if (B[k][j] == INF) continue;
                // 更新最小值
                C[i][j] = min(C[i][j], A[i][k] + B[k][j]);
            }
        }
    }
    return C;
}

// 矩阵快速幂
Mat mpow(Mat base, ll exp) {
    // 初始化结果矩阵为“广义单位矩阵”
    Mat res(N, vector<ll>(N, INF));
    for (int i = 0; i < N; i++) res[i][i] = 0;
    while (exp > 0) {
        if (exp & 1) res = mul(res, base);
        base = mul(base, base);
        exp >>= 1;
    }
    return res;
}
void solve(){
    cin >> N >> K;
    Mat G(N, vector<ll>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> G[i][j];
        }
    }
    // 计算矩阵 G 的 K 次幂
    Mat ansMat = mpow(G, K);
    // 输出结果：每个点 s 经过 K 步回到 s 的最小代价
    for (int i = 0; i < N; i++) {
        cout << ansMat[i][i] << "\n";
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int _=1;
    while(_--)solve();    
    return 0;
}
